const ok = telemetry
  && telemetry.version === '1.4.0'
  && typeof telemetry.init === 'function'
  && typeof telemetry.track === 'function';

if (!ok) {
  console.error('SMOKE_FAIL: @acme/telemetry did not load as expected');
  process.exit(1);
